'use strict';
const assert = require('node:assert/strict');
const { flattenOutline } = require('./solution');
let root = { id: '12000', children: [] };
for (let i = 11999; i >= 0; i--) root = { id: String(i), children: [root] };
let rows;
try { rows = flattenOutline(root); } catch (error) { throw new Error('valid depth-12000 outline failed: ' + error.name + ': ' + error.message); }
assert.equal(rows.length, 12001);
assert.deepEqual(rows[12000], { id: '12000', depth: 12000 });

prompt.text:
Repair the CommonJS module below. It must export exactly `{ flattenOutline }`.

`flattenOutline(root)` converts a nested outline to a flat preorder list:
- `null` represents an empty outline and returns `[]`.
- Every non-null node must be a non-array object with a non-empty string `id` and a `children` array.
- IDs must be unique across the outline.
- Reusing the same node object in more than one location, or forming a cycle, is malformed and throws `RangeError`.
- Return fresh `{ id, depth }` objects in preorder: a node before its children, and siblings in their original array order. Root depth is `0`.
- Throw `TypeError` for malformed node fields.
- Do not mutate any node or children array, and do not expose input aliases.

Return a corrected complete source file. Known-bad source:

```javascript
'use strict';

function flattenOutline(root) {
  if (root === null) return [];

  const result = [];
  const objects = new WeakSet();
  const ids = new Set();

  function visit(node, depth) {
    if (node === null || typeof node !== 'object' || Array.isArray(node)) {
      throw new TypeError('node must be an object');
    }
    if (objects.has(node)) throw new RangeError('node object reused');
    objects.add(node);
    if (typeof node.id !== 'string' || node.id.length === 0) {
      throw new TypeError('node id must be a non-empty string');
    }
    if (!Array.isArray(node.children)) throw new TypeError('children must be an array');
    if (ids.has(node.id)) throw new RangeError('duplicate node id');
    ids.add(node.id);

    result.push({ id: node.id, depth });
    for (let index = node.children.length - 1; index >= 0; index -= 1) {
      visit(node.children[index], depth + 1);
    }
  }

  visit(root, 0);
  return result;
}

module.exports = { flattenOutline };
```

