'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['flattenOutline']);
const { flattenOutline } = api;

assert.deepStrictEqual(flattenOutline(null), []);

const a1 = Object.freeze({ id: 'a1', children: Object.freeze([]) });
const a2 = Object.freeze({ id: 'a2', children: Object.freeze([]) });
const a = Object.freeze({ id: 'a', children: Object.freeze([a1, a2]) });
const b1 = Object.freeze({ id: 'b1', children: Object.freeze([]) });
const b = Object.freeze({ id: 'b', children: Object.freeze([b1]) });
const root = Object.freeze({ id: 'root', children: Object.freeze([a, b]) });
const expected = [
  { id: 'root', depth: 0 },
  { id: 'a', depth: 1 },
  { id: 'a1', depth: 2 },
  { id: 'a2', depth: 2 },
  { id: 'b', depth: 1 },
  { id: 'b1', depth: 2 }
];
assert.deepStrictEqual(flattenOutline(root), expected);
assert.deepStrictEqual(root.children, [a, b]);
assert.deepStrictEqual(a.children, [a1, a2]);

const first = flattenOutline(root);
const second = flattenOutline(root);
assert.notStrictEqual(first, second);
assert.notStrictEqual(first[0], second[0]);
first[0].id = 'changed';
first.push({ id: 'extra', depth: 9 });
assert.deepStrictEqual(second, expected);

assert.throws(() => flattenOutline([]), TypeError);
assert.throws(() => flattenOutline({ id: '', children: [] }), TypeError);
assert.throws(() => flattenOutline({ id: 1, children: [] }), TypeError);
assert.throws(() => flattenOutline({ id: 'x', children: null }), TypeError);
assert.throws(() => flattenOutline({ id: 'x', children: [null] }), TypeError);

const shared = { id: 'shared', children: [] };
assert.throws(() => flattenOutline({
  id: 'root',
  children: [
    { id: 'left', children: [shared] },
    { id: 'right', children: [shared] }
  ]
}), RangeError);

assert.throws(() => flattenOutline({
  id: 'root',
  children: [
    { id: 'same', children: [] },
    { id: 'same', children: [] }
  ]
}), RangeError);

const cyclic = { id: 'cycle', children: [] };
cyclic.children.push(cyclic);
assert.throws(() => flattenOutline(cyclic), RangeError);

